-- ------------------------------------------------------------------------------
-- 6. Articles Table (`articles`)
-- ------------------------------------------------------------------------------
CREATE TABLE `articles` (
  `id` VARCHAR(100) PRIMARY KEY,
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NULL,
  `category` VARCHAR(100) DEFAULT 'मुख्य समाचार',
  `categories` JSON NULL,
  `summary` TEXT NULL,
  `content` LONGTEXT NULL,
  `image` TEXT NULL,
  `images` JSON NULL,
  `author` VARCHAR(100) DEFAULT 'सनस्टार संवाददाता',
  `author_role` VARCHAR(100) NULL,
  `author_image` TEXT NULL,
  `read_time` VARCHAR(50) NULL,
  `province` VARCHAR(100) NULL,
  `tags` JSON NULL,
  `source` VARCHAR(100) DEFAULT 'SunstarNews.com',
  `time` VARCHAR(100) DEFAULT 'भर्खरै',
  `views` VARCHAR(50) DEFAULT '१.२ के',
  `views_count` INT DEFAULT 0,
  `likes_count` INT DEFAULT 12,
  `shares_count` INT DEFAULT 0,
  `comments_list` JSON NULL,
  `comments_count` INT DEFAULT 0,
  `is_published` TINYINT(1) DEFAULT 1,
  `is_featured` TINYINT(1) DEFAULT 0,
  `is_exclusive` TINYINT(1) DEFAULT 0,
  `published_at` TIMESTAMP NULL,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY `idx_articles_slug` (`slug`),
  KEY `idx_articles_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- 7. Advertisements Banner Table (`banners`)
-- ------------------------------------------------------------------------------
CREATE TABLE `banners` (
  `id` VARCHAR(100) PRIMARY KEY,
  `title` VARCHAR(255) NOT NULL,
  `image_url` TEXT NOT NULL,
  `target_url` TEXT NULL,
  `position` VARCHAR(100) NOT NULL,
  `is_active` TINYINT(1) DEFAULT 1,
  `clicks_count` INT DEFAULT 0,
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- 8. Opinions Table (`opinions`)
-- ------------------------------------------------------------------------------
CREATE TABLE `opinions` (
  `id` VARCHAR(100) PRIMARY KEY,
  `author_name` VARCHAR(100) NOT NULL,
  `author_role` VARCHAR(150) DEFAULT 'विचारक / विश्लेषक',
  `author_avatar` TEXT NULL,
  `title` VARCHAR(255) NOT NULL,
  `summary` TEXT NOT NULL,
  `content` LONGTEXT NULL,
  `reading_time` VARCHAR(50) DEFAULT '५ मिनेट अध्ययन',
  `created_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------------------
-- 9. Provinces & Districts (`provinces`, `districts`)
-- ------------------------------------------------------------------------------
CREATE TABLE `provinces` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name_ne` VARCHAR(100) NOT NULL,
  `name_en` VARCHAR(100) NOT NULL,
  `slug` VARCHAR(50) UNIQUE NOT NULL,
  `capital` VARCHAR(100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

